import { createSlice } from "@reduxjs/toolkit";
import { ValidateOcrDataReq, ValidateOcrDataRes } from "@src/domain/entities/card_dop/validateOcr";
import { validateOCRThunk } from "./thunk";
import { CardDOPBaseResponse } from "@src/domain/entities/common/cardDOPBaseApi";
interface DOPState {
    status: string,
    error: string,
    validateOCRData: ValidateOcrDataReq,
    validateOCRRes: CardDOPBaseResponse<ValidateOcrDataRes>
}
const initialState: DOPState = {
    status: 'idle',
    error: '',
    validateOCRData: {} as ValidateOcrDataReq,
    validateOCRRes: {} as CardDOPBaseResponse<ValidateOcrDataRes>,
}
export const DOPSlice = createSlice({
    name: 'loanRegister',
    initialState,
    reducers: {
        updateValidateOCRData: (state, action) => {
            // state.validateOCRData = { ...state.validateOCRData, ...action.payload };
            Object.assign(state.validateOCRData, action.payload);
        },
        updateValidateOCRRes: (state, action) => {
            // state.validateOCRData = { ...state.validateOCRData, ...action.payload };
            Object.assign(state.validateOCRRes, action.payload);
        },
        resetValidateOCRData: (state) => {
            state.validateOCRData = {} as ValidateOcrDataReq;
        },
        updateStatus: (state, action) => {
            state.status = action.payload;
        }
    },
    extraReducers: (builder) => {
        builder
            .addCase(validateOCRThunk.pending, (state) => {
                state.status = 'loading';
                state.error = '';
            })
            .addCase(validateOCRThunk.rejected, (state, action) => {
                state.status = 'failed';
                state.error = action.error.message ?? 'Failed to register loan demand';
            })
            .addCase(validateOCRThunk.fulfilled, (state, action) => {
                state.status = 'succeeded';
                console.log('\x1b[36m', 'validateOCRThunk => fulfilled', action.payload);
                // console.log('\x1b[36m', 'confirmLoanRegister => fulfilled', action.payload);
                if (action?.payload?.resultCode === '00') {
                    state.validateOCRRes = action.payload;
                } else {
                    state.error = action?.payload?.resultMessage || 'Failed to validate OCR';
                }

            })
    }
});

export const { updateValidateOCRData } = DOPSlice.actions