import React from 'react';
import { Text, StyleProp, TextStyle, Linking } from 'react-native';
import { Trans } from 'react-i18next';
import useCss from '@src/presentation/style';

interface Props {
    text: string;
    style?: StyleProp<TextStyle>;
    urls?: Record<string, string>;
    onPress?: (num?: number) => void; // Thêm prop để xử lý sự kiện nhấn vào highlight
}

const HighlightString: React.FC<Props> = ({ text, style, urls }) => {
    const css = useCss();

    const openBrowser = (url?: string) => {
        if (!url) return;
        Linking?.canOpenURL(url).then((supported) => {
            if (supported) {
                Linking?.openURL(url);
            } else {
                console.log('Không thể mở được link URI: ', url);
            }
        });
    };

    return (
        <Text style={[style]}>
            <Trans
                defaults={text}
                components={{
                    firstHighlight: <Text onPress={() => openBrowser(urls?.['firstHighlight'])} style={[css.text_red_600, css.font_bold, css.underline]} />,
                    secondHighlight: <Text onPress={() => openBrowser(urls?.['secondHighlight'])} style={[css.text_red_600, css.font_bold, css.underline]} />,
                    thirdHighlight: <Text onPress={() => openBrowser(urls?.['thirdHighlight'])} style={[css.text_red_600, css.font_bold, css.underline]} />,
                    fourthHighlight: <Text onPress={() => openBrowser(urls?.['fourthHighlight'])} style={[css.text_red_600, css.font_bold, css.underline]} />,
                    fifthHighlight: <Text onPress={() => openBrowser(urls?.['fifthHighlight'])} style={[css.text_red_600, css.font_bold, css.underline]} />,
                }}
            />
        </Text>
    );
};

export default HighlightString;
