import React, { useState } from 'react';
import { SafeAreaView, ScrollView, View, ImageBackground, TouchableOpacity } from 'react-native';
import { GradientButton, LoadingBlockerView, Spacer, Text, SimpleHeader, useTheme } from '@core/ui';
import useCSS from '@src/presentation/style';
import { RouteProp, useNavigation, useRoute } from '@react-navigation/native';
import { MainStackNavigationProp, MainStackParamList } from '@src/presentation/navigation/MainNavigator';
import { useTranslation } from 'react-i18next';
import { useSelector } from '@src/lib/redux';
import { selectListCreditCard } from '../dop_login/redux/selector';
import CustomHeader from '../components/header/CustomHeader';

const DOPCreditCardScreen = () => {
    const { theme } = useTheme();
    const css = useCSS();
    const navigation = useNavigation<MainStackNavigationProp>();
    const { t } = useTranslation(['module_dop']);
    const data = useSelector(selectListCreditCard);

    const [status, setStatus] = useState('idle');
    const [cardActive, setCardActive] = useState('');

    const renderCardNumber = (number: string) => {
        let tmp = number.split('');
        const length = tmp.length;
        let hideLength = tmp.length - 5;

        switch (hideLength) {
            case -1:
                hideLength = 1;
                break;
            case -2:
            case -3:
            case -4:
                hideLength = 0;
                break;

            default:
                break;
        }

        for (let index = 0; index < length; index++) {
            if (index <= hideLength) {
                tmp[index] = '*';
            }
        }

        return tmp.join('');
    };

    const onCardSelect = (item: any) => {
        setCardActive(item.accountNo);
    };

    const handleSubmit = () => {
        if (!cardActive) {
            return;
        }
        navigation.navigate('DOP_card_step1');
    };

    return (
        <ImageBackground source={require('@src/assets/images/bg_body.jpg')} resizeMode='cover' style={[css.flex_1]}>
            <SafeAreaView style={[css.flex_1]}>
                <CustomHeader title={t('screen_password.credit_card_issuance')} />
                {status === 'loading' ? <LoadingBlockerView containerStyle={{ backgroundColor: 'rgba(255,255,255,0.5)', zIndex: 100000 }} /> : null}
                <ScrollView showsHorizontalScrollIndicator={false} showsVerticalScrollIndicator={false}>
                    <View style={[css.flex_1, css.mt_xLarge, css.mh_medium]}>
                        <Text style={[css.text_title_200, css.font_semibold, css.text_black, css.mt_small]}>
                            {t('screen_password.choose')}{' '}
                            <Text style={[css.text_title_200, css.font_semibold, css.text_red_600]}>{t('screen_password.payment_account')}</Text>{' '}
                            {t('screen_password.link_debit_card')}
                        </Text>
                        <Spacer height={24} />
                        {data.map((item, index) => {
                            return (
                                <TouchableOpacity
                                    onPress={() => onCardSelect(item)}
                                    key={'_key_card' + index}
                                    style={[
                                        index > 0 && css.mt_regular,
                                        { height: theme.Size.hs(56) },
                                        css.pv_base,
                                        css.ph_medium,
                                        css.justify_center,
                                        css.rounded_base,
                                        css.border_1,
                                        css.border_neutral_400,
                                        css.bg_white,
                                        cardActive === item.accountNo && { ...css.border_2, borderColor: theme.Colors.Main.Red },
                                    ]}>
                                    <Text style={[css.text_black, css.text_body, css.font_medium]}>{renderCardNumber(item.accountNo)}</Text>
                                </TouchableOpacity>
                            );
                        })}
                    </View>
                    <View style={[css.mt_auto, css.p_medium]}>
                        <GradientButton
                            title={t('screen_password.confirm')}
                            gradientProps={!cardActive ? { type: 'secondary' } : { type: 'primary' }}
                            onPress={handleSubmit}
                        />
                    </View>
                </ScrollView>
            </SafeAreaView>
        </ImageBackground>
    );
};

export default DOPCreditCardScreen;
