import { injectable } from 'inversify';
import { Query } from '@src/domain/models/query';
import { HttpService } from '@core/service';
import { BASE_URL_CARD_DOP_API } from '@src/config';
import { CardDOPBaseResponse } from '@src/domain/entities/common/cardDOPBaseApi';
import { commonService } from '@src/infrastructure/network/networkService';
import { ICardListAvailableRepository } from '@src/domain/interfaces/card_dop/cardListAvailable';
import { CardListAvailableDataReq, CardListAvailableDataRes } from '@src/domain/entities/card_dop/cardListAvailable';

@injectable()
export class CardListAvailableRepository
    extends HttpService
    implements ICardListAvailableRepository {
    constructor() {
        super({ baseURL: BASE_URL_CARD_DOP_API });
    }

    async cardListAvailable<TParameter>(query: Query<TParameter>): Promise<CardDOPBaseResponse<CardListAvailableDataRes[]>> {
        const request = query.query as unknown as CardListAvailableDataReq;
        const url = '/dop-card-list-available';
        const response = await this.post(url, request, {
            headers: commonService.getHeader({ 'X-CHANNEL': 'mfe-dop-mobile' }),
        })                
        console.log('\x1b[31m thieuvq3 response dop-card-list-available: ', JSON.stringify(response, null, 4));
        return response.data as CardDOPBaseResponse<CardListAvailableDataRes[]>;
    }
}
