import { injectable } from 'inversify';
import { Query } from '@src/domain/models/query';
import { HttpService } from '@core/service';
import { BASE_URL_CARD_DOP_API } from '@src/config';
import { CardDOPBaseResponse } from '@src/domain/entities/common/cardDOPBaseApi';
import { commonService } from '@src/infrastructure/network/networkService';
import { ICardDetailsRepository } from '@src/domain/interfaces/card_dop/cardDetails';
import { CardDetailsDataReq, CardDetailsDataRes } from '@src/domain/entities/card_dop/cardDetails';

@injectable()
export class CardDetailsRepository
    extends HttpService
    implements ICardDetailsRepository {
    constructor() {
        super({ baseURL: BASE_URL_CARD_DOP_API });
    }

    async cardDetails<TParameter>(query: Query<TParameter>): Promise<CardDOPBaseResponse<CardDetailsDataRes>> {
        const request = query.query as unknown as CardDetailsDataReq;
        const url = '/dop-card-details';
        const response = await this.post(url, request, {
            headers: commonService.getHeader({ 'X-CHANNEL': 'mfe-dop-mobile' }),
        })                
        console.log('\x1b[31m thieuvq3 response dop-card-details: ', JSON.stringify(response, null, 4));
        return response.data as CardDOPBaseResponse<CardDetailsDataRes>;
    }
}
