import React, { useEffect, useRef, useState } from 'react';
import { SafeAreaView, ScrollView, View, ImageBackground } from 'react-native';
import { RouteProp, useNavigation, useRoute } from '@react-navigation/native';
import { useTranslation } from 'react-i18next';
import Keychain, { BIOMETRY_TYPE } from 'react-native-keychain';
import { BiometryTypes } from 'react-native-biometrics';
import { LoadingBlockerView, DynamicHeader, Spacer, Text, createStyles } from '@core/ui';
import { IS_IOS, KEYCHAIN_BIOMETRIC_TYPE, saveWithBiometric, Storage, STORAGE_KEY, KeychainServiceName, hasUsernameInKeychain, clear } from '@core/service';
import { useSelector } from '@src/lib/redux';
import { selectICData } from '../dop_ocr/redux/selector';
import { MainStackNavigationProp, MainStackParamList } from '@src/presentation/navigation/MainNavigator';
import useCSS from '@src/presentation/style';
import { HDBankLogoDash, IFaceID, ITouchID } from '@src/assets/images/icons';
import PinInputWrapper from './components/PinInputWrapper';
import BiometricButton from './components/BiometricButton';

export type SUPPORTED_BIOMETRIC = (typeof KEYCHAIN_BIOMETRIC_TYPE)[keyof typeof KEYCHAIN_BIOMETRIC_TYPE];

const ConfirmPinScreen = () => {
    const styles = useStyles();
    const css = useCSS();
    const { t } = useTranslation(['module_dop']);
    const navigation = useNavigation<MainStackNavigationProp>();
    const route = useRoute<RouteProp<MainStackParamList, 'confirm_pin_screen'>>();
    const previousPin = route.params?.pin || '123456';

    const ICData = useSelector(selectICData);
    const { phoneNumber }: any = ICData;

    const [status, setStatus] = useState('idle');
    const [isEnabled, setIsEnabled] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [biometricType, setBiometricType] = useState<'FaceID' | 'TouchID' | 'Fingerprint' | null>(null);
    const [isBiometricsSupported, setIsBiometricsSupported] = useState<boolean | null>(null);

    const pinInputRef = useRef<any>(null);

    useEffect(() => {
        setTimeout(() => {
            pinInputRef.current?.focus();
        }, 100);
    }, []);

    useEffect(() => {
        (async () => {
            try {
                const previousSupportedType = await Storage.retrieve(STORAGE_KEY.BIOMETRIC_SUPPORTED_TYPE);
                const supportedType = (await Keychain.getSupportedBiometryType()) as SUPPORTED_BIOMETRIC;
                if (!previousSupportedType) {
                    Storage.save(STORAGE_KEY.BIOMETRIC_SUPPORTED_TYPE, supportedType);
                }
                const available = !!supportedType;
                const biometryType = supportedType || previousSupportedType;
                if (available) {
                    setIsBiometricsSupported(true);
                    if (biometryType === BiometryTypes.FaceID) {
                        setBiometricType('FaceID');
                    } else if (biometryType === BiometryTypes.TouchID && IS_IOS) {
                        setBiometricType('TouchID');
                    } else if (biometryType === BiometryTypes.TouchID && !IS_IOS) {
                        setBiometricType('Fingerprint');
                    } else {
                        setBiometricType(biometryType);
                    }
                } else {
                    setIsBiometricsSupported(false);
                }
            } catch (e) {
                setIsBiometricsSupported(false);
                console.log('biometrics error', e);
            }
        })();
    }, []);

    const handleOnSubmit = (pin: string) => {
        if (pin === previousPin) {
            navigation.navigate('DOP_card_step1')
            if (isBiometricsSupported && isEnabled) {
                handleBiometric(pin);
            } else {
                setError('');
                navigation.navigate('DOP_card_step1')
            }
            pinInputRef.current?.hide();
        } else {
            setError(t('screen_password.error_pin_not_match'));
        }
    };

    const handleBiometric = async (pin: string) => {
        if (isBiometricsSupported) {
            try {
                await saveWithBiometric(phoneNumber || '', pin, KeychainServiceName.PASSWORD_BIOMETRICS_SERVICE_NAME);
                await hasUsernameInKeychain(phoneNumber || '', KeychainServiceName.PASSWORD_BIOMETRICS_SERVICE_NAME);
            } catch (error) {
                await clear(KeychainServiceName.PASSWORD_BIOMETRICS_SERVICE_NAME);
                setIsEnabled(false);
            } finally {
                setError('');
                navigation.navigate('DOP_card_step1')
            }
        }
    };

    return (
        <ImageBackground source={require('@src/assets/images/bg_body.jpg')} resizeMode='cover' style={[css.flex_1]}>
            <SafeAreaView style={[css.flex_1]}>
                <DynamicHeader
                    onBackPress={() => {
                        navigation.goBack();
                    }}
                    MainComponent={() => (
                        <View style={styles.mainContainer}>
                            <HDBankLogoDash style={styles.mainLogo} />
                        </View>
                    )}
                />
                {status === 'loading' ? <LoadingBlockerView containerStyle={{ backgroundColor: 'rgba(255,255,255,0.5)', zIndex: 100000 }} /> : null}
                <ScrollView showsHorizontalScrollIndicator={false} showsVerticalScrollIndicator={false}>
                    <View style={[css.flex_1, css.mt_xLarge, css.mh_medium]}>
                        <Text style={[css.text_title_200, css.font_semibold, css.text_black]}>
                            {t('screen_password.create')}{' '}
                            <Text style={[css.text_title_200, css.font_semibold, css.text_red_600]}>{t('screen_password.pin')}</Text>{' '}
                            {t('screen_password.to_login')}
                        </Text>
                        <Spacer height={8} />
                        <Text style={[css.text_subheadline, css.text_black]}>{t('screen_password.sub_title_confirm_pin')}.</Text>
                        <Spacer height={64} />
                        <View style={[css.w_full, css.items_center]}>
                            <PinInputWrapper cellCount={6} onSubmit={handleOnSubmit} ref={pinInputRef} isMask={true} keyboardType={'number-pad'} />
                            <Spacer height={16} />
                            <Text style={[css.text_subheadline, css.text_red_600, css.text_center]}>{error}</Text>
                        </View>
                        <Spacer height={64} />
                        {isBiometricsSupported && biometricType === BIOMETRY_TYPE.FACE_ID && (
                            <BiometricButton {...{ isEnabled, setIsEnabled }} icon={<IFaceID />} toggleText='screen_password.face_id_toggle' />
                        )}
                        {isBiometricsSupported && biometricType === BIOMETRY_TYPE.TOUCH_ID && (
                            <BiometricButton {...{ isEnabled, setIsEnabled }} icon={<ITouchID />} toggleText='screen_password.touch_id_toggle' />
                        )}
                        {isBiometricsSupported && biometricType === BIOMETRY_TYPE.FINGERPRINT && (
                            <BiometricButton {...{ isEnabled, setIsEnabled }} icon={<ITouchID />} toggleText='screen_password.fingerprint_toggle' />
                        )}
                    </View>
                </ScrollView>
            </SafeAreaView>
        </ImageBackground>
    );
};

export default ConfirmPinScreen;

const useStyles = createStyles((theme) => ({
    mainContainer: {
        flex: 1,
        alignItems: 'center',
        justifyContent: 'center',
        gap: theme.Size.Horizontal.Regular,
        height: theme.Size.Vertical.xxxLarge,
    },
    mainLogo: {
        height: theme.Size.Vertical.xxxLarge,
    },
    container: {
        flexDirection: 'row',
        alignItems: 'center',
        backgroundColor: theme.Colors.Background.White,
        padding: theme.Size.Horizontal.Regular,
        borderRadius: theme.BorderRadius.md,
        borderColor: theme.Colors.Border.Neutral300,
        borderWidth: theme.Size.ms(1),
    },
    icon: {
        marginRight: theme.Size.Horizontal.Regular,
    },
    text: {
        ...theme.Typography.TextBody.Regular,
        flex: 1,
    },
}));
