import { ActionButton, createStyles, GradientButton, LoadingBlockerView, SimpleHeader, Spacer, Theme, useTheme } from '@core/ui';
import React, { ReactNode, useEffect, useState } from 'react';
import { Alert, Image, ImageBackground, SafeAreaView, ScrollView, TouchableOpacity, View } from 'react-native';
import { Text } from '@core/ui';
import useCSS from '@src/presentation/style';
import { SectionField, sectionFieldProps } from './components/sectionField';
import { useSelector } from 'react-redux';
import { selectCareers, selectPositions, selectStatusDopConfirm } from './redux/selector';
import { useDispatch } from '@src/lib/redux';

import { formatDate, formatDateFDash2Splash, useTranslation } from '@core/service';
import { useNavigation } from '@react-navigation/native';
import { MainStackNavigationProp } from '@src/presentation/navigation/MainNavigator';
import BottomSheetInput from '@src/presentation/components/bottomSheetInput';

import { validator } from '@src/utils/validator';
import getImg from '@src/utils/getImg';
import BottomSheetRadios from '../components/BottomSheetRadios';
import BottomSheetAddress from '../components/bottomSheetAddress/bottomSheetAddress';

import type { District } from '@src/domain/entities/address/district';
import type { Province } from '@src/domain/entities/address/province';
import type { Ward } from '@src/domain/entities/address/ward';
import { selectICData, selectNFCData } from '../dop_ocr/redux/selector';
import { DOPSlice } from '../redux/slice';
import { ValidateOcrDataReq, ValidateOcrDataRes } from '@src/domain/entities/card_dop/validateOcr';
import { selectErrorMsg, selectStatus, selectValidateOCRData } from '../redux/selector';
import { validateOCRThunk } from '../redux/thunk';
import { CardDOPBaseResponse } from '@src/domain/entities/common/cardDOPBaseApi';
import { useCustomNavigation } from '@src/hooks/useCustomNavigation';

import { Career, Position } from '@src/domain/entities/card_dop/getCareersPositions';
import { fetchGetCareersPositions } from './thunk';
import { CardDOPBaseRequest } from '@src/domain/entities/common/cardDOPBaseApi';
import { GetCareersPositionsDataReq } from '@src/domain/entities/card_dop/getCareersPositions';
import CustomHeader from '../components/header/CustomHeader';
import HighlightTitle from '../components/text/HighlightTitle';

export class Query<TParameter> {
    query: TParameter;

    constructor(params: { query: TParameter }) {
        this.query = params.query;
    }
}

const initialJob = { careerId: '', careerName: '', businessId: '', industryId: '' };
const initialPos = { careerId: '', positionId: '', positionName: '', occupationCode: '' };

const DOPConfirmScreen = () => {
    const styles = useStyles();
    const css = useCSS();
    const { theme } = useTheme();
    const dispatch = useDispatch();
    const navigation = useNavigation<MainStackNavigationProp>();
    const { navigate } = useCustomNavigation();
    const { t } = useTranslation(['confirm']);

    const careers = useSelector(selectCareers);
    const positions = useSelector(selectPositions);
    const ICData = useSelector(selectICData);
    const NFCData = useSelector(selectNFCData);
    const status = useSelector(selectStatus);
    const statusDopConfirm = useSelector(selectStatusDopConfirm);
    const errorMsg = useSelector(selectErrorMsg);
    const {
        addrProvinceName,
        addrDetail,
        addrDistrictName,
        addrWardName,
        addrProvinceId,
        addrDistrictId,
        addrWardId,
        businessId,
        businessName,
        positionId,
        positionName,
        referralCode,
        oldIdentityNumber,
        careerName
    } = useSelector(selectValidateOCRData);

    const [listEmpty, setListEmpty] = useState<Record<string, boolean>>({});

    const [showBSOldGlobalId, setShowBSOldGlobalId] = useState(false);
    const [showBSAddressCurrent, setShowBSAddressCurrent] = useState(false);
    const [showBSJob, setShowBSJob] = useState(false);
    const [showBSJobPosition, setShowBSJobPosition] = useState(false);
    const [showBSReferralCode, setShowBSReferralCode] = useState(false);

    const [positionsDisplay, setPositionsDisplay] = useState<Array<Position>>([]);
    const [jobSelected, setJobSelected] = useState<Career>(initialJob);
    const [jobSelectedPosition, setJobSelectedPosition] = useState<Position>(initialPos);
    const [showBottomSheetInputFullAddress, setShowBottomSheetInputFullAddress] = useState(false);
    const [showBottomSheetInputCCCD, setShowBottomSheetInputCCCD] = useState(false);
    const [showBottomSheetInputName, setShowBottomSheetInputName] = useState(false);
    const [showBottomSheetInputDOB, setShowBottomSheetInputDOB] = useState(false);
    const [cccd, setCCCD] = useState<string>('');
    const [name, setName] = useState<string>('');
    const [dob, setDOB] = useState<string>('');

    useEffect(() => {
        dispatch(fetchGetCareersPositions({} as CardDOPBaseRequest<GetCareersPositionsDataReq>['data']));
    }, []);

    useEffect(() => {
        setPositionsDisplay(positions);
        if (positions?.length > 0) {
            setShowBSJob(true);
        }
    }, [positions]);

    const identityCard: sectionFieldProps[] = [
        {
            id: 'noiCap',
            title: t('customer_info.issue_place'),
            divider: false,
            isRequired: false,
            value: ICData?.placeOfIssue || '',
            fn: () => { },
            allowEdit: false,
        },
        {
            id: 'ngayCap',
            title: t('customer_info.issue_date'),
            divider: true,
            fn: () => { },
            isRequired: false,
            value: formatDateFDash2Splash(ICData?.dateOfIssue || '') || '',
            showArrow: false,
            allowEdit: false,
        },
        {
            id: 'ngayHetHan',
            title: t('customer_info.expire_date'),
            divider: true,
            fn: () => { },
            value: formatDateFDash2Splash(ICData?.dateOfExpiry || '') || '',
            showArrow: false,
            allowEdit: false,
        },
        {
            id: 'oldGlobalId',
            title: t('customer_info.old_card_number'),
            divider: true,
            fn: () => setShowBSOldGlobalId(true),
            isRequired: false,
            value: NFCData?.nfcOldIdNumber || oldIdentityNumber || '',
            showArrow: true,
            allowEdit: true,
        },
    ];
    const customerCard: sectionFieldProps[] = [
        {
            id: 'ngaySinh',
            title: t('customer_info.dob'),
            divider: false,
            fn: () => { setShowBottomSheetInputDOB(true) },
            isRequired: false,
            value: dob || formatDateFDash2Splash(ICData?.dateOfBirth || '') || '',
            showArrow: false,
            allowEdit: false,
        },
        {
            id: 'gioiTinh',
            title: t('customer_info.gender'),
            divider: true,
            isRequired: false,
            value: ICData?.gender ? (ICData.gender === 'M' ? t('customer_info.male') : t('customer_info.female')) : '',
        },
        {
            id: 'noiThuongTru',
            title: t('customer_info.address'),
            divider: true,
            isRequired: false,
            value: ICData?.address || '',
        },
        {
            id: 'noiOHienTai',
            title: t('customer_info.contact_address'),
            divider: true,
            fn: () => setShowBSAddressCurrent(true),
            isRequired: false,
            value: `${addrDetail ? `${addrDetail}, ` : ''}${addrWardName ? `${addrWardName}, ` : ''}${addrDistrictName ? `${addrDistrictName}, ` : ''}${addrProvinceName ? `${addrProvinceName}` : ''
                }`,
            showArrow: true,
            allowEdit: true,
        },
        {
            id: 'congViec',
            title: t('customer_info.job'),
            divider: true,
            fn: () => setShowBSJob(true),
            isRequired: false,
            value: careerName || businessName || '',
            showArrow: true,
            allowEdit: true,
        },
        {
            id: 'viTriCongViec',
            title: t('customer_info.position'),
            divider: true,
            fn: () => setShowBSJobPosition(true),
            isRequired: true,
            value: positionName || '',
            showArrow: true,
            allowEdit: true,
        },
    ];

    const handleConfirm = () => {
        dispatch(validateOCRThunk()).then((res) => {
            if ((res.payload as CardDOPBaseResponse<ValidateOcrDataRes>)?.resultCode === '00') {
                navigate('dop_password_screen');
            } else {
                Alert.alert('Thông báo', (res.payload as CardDOPBaseResponse<ValidateOcrDataRes>)?.resultMessage || 'Failed to register loan demand');
            }
        });
    };
    const handleSubmitOldGlobalId = (value: string) => {
        setShowBSOldGlobalId(false);
        dispatch(DOPSlice.actions.updateValidateOCRData({ oldIdentityNumber: value } as ValidateOcrDataReq));
    };

    const onJobSelected = (item: Career) => {
        const clonePos = positions?.filter?.((x) => x?.careerId === item.careerId);
        let clearPos = {};
        setJobSelected(item);
        if (item.careerId !== jobSelected.careerId) {
            setJobSelectedPosition(initialPos);
            clearPos = { positionId: '', positionName: '' };
        }
        dispatch(
            DOPSlice.actions.updateValidateOCRData({
                careerId: item.careerId,
                careerName: item.careerName,
                ...clearPos,
            } as ValidateOcrDataReq),
        );
        setPositionsDisplay(clonePos);
        setShowBSJobPosition(true);
    };

    const onPositionSelected = (item: Position) => {
        setJobSelectedPosition(item);
        dispatch(DOPSlice.actions.updateValidateOCRData({ positionId: item.positionId, positionName: item.positionName } as ValidateOcrDataReq));
        if (!jobSelected.careerId) {
            const job = careers?.find((x) => x.careerId === item.careerId);
            const clonePos = positions?.filter?.((x) => x?.careerId === item.careerId);
            setJobSelected(job || initialJob);
            dispatch(DOPSlice.actions.updateValidateOCRData({ positionId: clonePos?.[0]?.positionId || '', positionName: clonePos?.[0]?.positionName || '' } as ValidateOcrDataReq));
            setPositionsDisplay(clonePos);
        }
    };
    const handleSubmitProvince = (province: Province) => {
        dispatch(DOPSlice.actions.updateValidateOCRData({ addrProvinceName: province.name, addrProvinceId: province.id, contactProvinceId: province.id, } as ValidateOcrDataReq));
    };
    const handleSubmitDistrict = (district: District) => {
        dispatch(DOPSlice.actions.updateValidateOCRData({ addrDistrictName: district.name, addrDistrictId: district.id, contactDistrictId: district.id } as ValidateOcrDataReq));
    };
    const handleSubmitWard = (ward: Ward) => {
        setShowBottomSheetInputFullAddress(true);
        setShowBSAddressCurrent(false);
        dispatch(DOPSlice.actions.updateValidateOCRData({ addrWardName: ward.name, addrWardId: ward.id, contactWardId: ward.id } as ValidateOcrDataReq));
    };
    const handleSubmitAddress = (value: string) => {
        setShowBottomSheetInputFullAddress(false);
        dispatch(DOPSlice.actions.updateValidateOCRData({ addrDetail: value, contactDetail: value } as ValidateOcrDataReq));
    };
    const handleSubmitConsult = (value: string) => {
        setShowBSReferralCode(false);
        dispatch(DOPSlice.actions.updateValidateOCRData({ referralCode: value } as ValidateOcrDataReq));
    };
    const handleSubmitCCCD = (value: string) => {
        setShowBottomSheetInputCCCD(false);
        setCCCD(value);
        dispatch(DOPSlice.actions.updateValidateOCRData({ identityNumber: value } as ValidateOcrDataReq));
    };
    const handleSubmitName = (value: string) => {
        setShowBottomSheetInputName(false);
        setName(value);
        dispatch(DOPSlice.actions.updateValidateOCRData({ fullName: value } as ValidateOcrDataReq));
    };
    const handleSubmitDOB = (value: string) => {
        setShowBottomSheetInputDOB(false);
        setDOB(value);
        dispatch(DOPSlice.actions.updateValidateOCRData({ dob: value } as ValidateOcrDataReq));
    };

    return (
        <>
            <ImageBackground source={getImg('/assets/images/bg/bg_body.jpg')} resizeMode='cover'>
                {(status === 'loading' || statusDopConfirm === 'loading') && (
                    <LoadingBlockerView containerStyle={{ backgroundColor: 'rgba(255,255,255,0.5)', zIndex: 100000 }} />
                )}
                <SafeAreaView>
                    <CustomHeader title={t('header_title')} />
                    <ScrollView style={[{ marginBottom: theme.Size.Vertical.xLarge }]}>
                        <View style={[css.ph_medium, css.pb_xxLarge, css.mb_regular]}>
                            {/* <Picker {...{ values, defaultValue }} /> */}
                            <View style={[css.mt_medium]}>
                                {/* <Text style={styles.title}>{t('title')}</Text> */}
                                <HighlightTitle
                                    title={t('title')}
                                    subtitle={t('sub_title')}
                                />
                            </View>
                            {/* section customer info */}
                            <View>
                                <View style={styles.sectionWrapper}>
                                    <ImageBackground
                                        source={getImg('/assets/images/bg/bg_header_Loan_registration_card.png')}
                                        imageStyle={[css.rounded_tl_base, css.rounded_tr_base]}>
                                        <View style={[css.flex_1, css.row, css.items_center, css.mt_medium, css.pb_regular]}>
                                            <Image
                                                source={getImg('/assets/images/icons/icon_id.png')}
                                                style={[
                                                    css.ml_medium,
                                                    css.mr_regular,
                                                    { width: theme.Size.Horizontal.Huge, height: theme.Size.Vertical.Huge, resizeMode: 'contain' },
                                                ]}
                                            />
                                            <View style={[css.flex_1, css.row, css.items_center, css.justify_between, css.w_100pc]}>
                                                <View>
                                                    <Text style={theme.Typography.TextSubheadline.Regular}>{t('customer_info.globalId')}</Text>
                                                    <Text style={theme.Typography.Title200.Semibold} onPress={() => { setShowBottomSheetInputCCCD(true) }}>{cccd || ICData?.idNumber || ''}</Text>
                                                </View>
                                            </View>
                                        </View>
                                    </ImageBackground>
                                    <View style={[css.pv_medium]}>
                                        {identityCard.map((item, index) => (
                                            <SectionField
                                                key={index}
                                                title={item.title}
                                                render={item.render}
                                                divider={item.divider}
                                                fn={item?.fn}
                                                isRequired={item?.isRequired && !!listEmpty[item?.id || '']}
                                                value={item?.value}
                                                showArrow={item?.showArrow}
                                                allowEdit={item?.allowEdit}
                                            />
                                        ))}
                                    </View>
                                </View>
                            </View>

                            {/* section loan info */}
                            <View>
                                <View style={styles.sectionWrapper}>
                                    <ImageBackground
                                        source={getImg('/assets/images/bg/bg_header_Loan_registration_card.png')}
                                        imageStyle={[css.rounded_tl_base, css.rounded_tr_base]}>
                                        <View style={[css.flex_1, css.row, css.items_center, css.mt_medium, css.pb_regular]}>
                                            <Image
                                                source={getImg('/assets/images/icons/default_avatar.png')}
                                                style={[
                                                    css.ml_medium,
                                                    css.mr_regular,
                                                    { width: theme.Size.Horizontal.Huge, height: theme.Size.Vertical.Huge, resizeMode: 'contain' },
                                                ]}
                                            />
                                            <View style={[css.flex_1, css.row, css.items_center, css.justify_between, css.w_100pc]}>
                                                <View>
                                                    <Text style={theme.Typography.TextSubheadline.Regular}>{t('customer_info.name')}</Text>
                                                    <Text style={theme.Typography.Title200.Semibold} onPress={() => { setShowBottomSheetInputName(true) }} >{name || ICData?.name || ''}</Text>
                                                </View>
                                            </View>
                                        </View>
                                    </ImageBackground>
                                    <View style={[css.pv_medium]}>
                                        {customerCard.map((item, index) => (
                                            <SectionField
                                                key={index}
                                                title={item.title}
                                                render={item.render}
                                                divider={item.divider}
                                                fn={item?.fn}
                                                isRequired={item?.isRequired && !!listEmpty[item?.id || '']}
                                                value={item?.value}
                                                showArrow={item?.showArrow}
                                                allowEdit={item?.allowEdit}
                                            />
                                        ))}
                                    </View>
                                </View>
                                <Spacer height={16} />
                                <TouchableOpacity onPress={() => setShowBSReferralCode(true)}>
                                    <View style={[css.p_medium, css.rounded_medium, css.shadow_100, css.bg_white]}>
                                        <View style={[css.row, css.justify_between, css.items_center]}>
                                            <Text style={[css.text_subheadline, css.text_neutral_600, css.font_400]}>{t('introduce_info.title')}</Text>
                                            <View style={[css.row, css.items_center]}>
                                                {true && <Text style={[css.text_subheadline, css.font_semibold]}>{referralCode}</Text>}
                                                <Image
                                                    style={[
                                                        { height: theme.Size.Vertical.Regular, width: theme.Size.Horizontal.Base, resizeMode: 'contain' },
                                                        css.ml_base,
                                                    ]}
                                                    source={getImg('/assets/images/icons/right_arrow.png')}
                                                />
                                            </View>
                                        </View>
                                    </View>
                                </TouchableOpacity>
                            </View>
                            <Spacer height={28} />
                            <View style={[css.row]}>
                                <View style={[css.flex_1]}>
                                    <ActionButton title={t('re_capture')} type='secondary' onPress={() => { navigation.navigate('EKYC_identity_card') }} />
                                </View>
                                <Spacer width={12} />
                                <View style={[css.flex_1]}>
                                    <GradientButton gradientProps={{ type: 'primary' }} title={t('submit')} onPress={handleConfirm} />
                                </View>
                            </View>
                            <Spacer height={16} />
                        </View>
                    </ScrollView>
                </SafeAreaView>
            </ImageBackground>
            {/* section component */}

            <BottomSheetRadios
                show={showBSJob}
                data={careers}
                keyValue='careerId'
                keyLabel='careerName'
                itemActive={jobSelected}
                onSelected={onJobSelected}
                title={t('job_screen.occupation')}
                desc={t('job_screen.occupationDescription')}
                onClose={() => setShowBSJob(false)}
            />
            <BottomSheetRadios
                show={showBSJobPosition}
                data={positionsDisplay}
                keyValue='positionId'
                keyLabel='positionName'
                itemActive={jobSelectedPosition}
                onSelected={onPositionSelected}
                title={t('job_screen.jobPosition')}
                desc={t('job_screen.positionDescription')}
                onClose={() => setShowBSJobPosition(false)}
            />
            <BottomSheetInput
                title={t('customer_info.title_input_old_card_number')}
                label={t('customer_info.label_input_old_card_number')}
                labelSubmit={t('customer_info.label_submit')}
                inputType='numeric'
                show={showBSOldGlobalId}
                onClose={() => {
                    setShowBSOldGlobalId(false);
                }}
                onSubmit={handleSubmitOldGlobalId}
                textInputProps={{
                    value: '',
                    placeholder: '',
                    maxLength: 12,
                    selectionColor: theme.Colors.Main.Orange,
                }}
                validate={validator.validateGlobalId}
            />
            <BottomSheetInput
                title={t('introduce_info.title_input_HDCode')}
                label={t('introduce_info.label_input_HDCode')}
                labelSubmit={t('introduce_info.label_submit')}
                inputType='numeric'
                show={showBSReferralCode}
                onClose={() => {
                    setShowBSReferralCode(false);
                }}
                onSubmit={handleSubmitConsult}
                textInputProps={{
                    value: '',
                    placeholder: '',
                    maxLength: 50,
                    selectionColor: theme.Colors.Main.Orange,
                }}
                validate={validator.validateReferralCode}
            />
            <BottomSheetAddress
                show={showBSAddressCurrent}
                onClose={() => {
                    setShowBSAddressCurrent(false);
                }}
                selectProvince={handleSubmitProvince}
                selectDistrict={handleSubmitDistrict}
                selectWard={handleSubmitWard}
            />
            <BottomSheetInput
                title={t('customer_info.label_title_input_address')}
                label={t('customer_info.label_input_address')}
                labelSubmit={t('customer_info.label_submit')}
                show={showBottomSheetInputFullAddress}
                onClose={() => {
                    setShowBottomSheetInputFullAddress(false);
                    setShowBSAddressCurrent(false);
                }}
                onSubmit={handleSubmitAddress}
                textInputProps={{
                    value: '',
                    placeholder: '',
                    maxLength: 50,
                    selectionColor: theme.Colors.Main.Orange,
                }}
                validate={validator.validateAddress}
            />
            <BottomSheetInput
                title={'CCCD-test'}
                label={'CCCD-test'}
                labelSubmit={'CCCD-test'}
                show={showBottomSheetInputCCCD}
                onClose={() => {
                    setShowBottomSheetInputCCCD(false);
                }}
                onSubmit={handleSubmitCCCD}
                textInputProps={{
                    value: '',
                    placeholder: '',
                    maxLength: 12,
                    selectionColor: theme.Colors.Main.Orange,
                }}
                validate={validator.validateGlobalId}
            />
            <BottomSheetInput
                title={'CCCD-test'}
                label={'CCCD-test'}
                labelSubmit={'CCCD-test'}
                show={showBottomSheetInputName}
                onClose={() => {
                    setShowBottomSheetInputName(false);
                }}
                onSubmit={handleSubmitName}
                textInputProps={{
                    value: '',
                    placeholder: '',
                    maxLength: 50,
                    selectionColor: theme.Colors.Main.Orange,
                }}
                validate={validator.validateFullName}
            />
            <BottomSheetInput
                title={'CCCD-test'}
                label={'CCCD-test'}
                labelSubmit={'CCCD-test'}
                show={showBottomSheetInputDOB}
                onClose={() => {
                    setShowBottomSheetInputDOB(false);
                }}
                onSubmit={handleSubmitDOB}
                textInputProps={{
                    value: '',
                    placeholder: '',
                    maxLength: 50,
                    selectionColor: theme.Colors.Main.Orange,
                }}
            // validate={validator.validateFullName}
            />
        </>
    );
};

const useStyles = createStyles((theme: Theme) => {
    return {
        value: {
            ...theme.Typography.TextSubheadline.SemiBold,
            maxWidth: theme.Size.Horizontal.Titanic,
        },
        title: {
            ...theme.Typography.Title200.Semibold,
        },
        titleWrapper: {
            marginTop: theme.Size.Vertical.Medium,
            justifyContent: 'center',
        },
        highLightAction: {
            ...theme.Typography.TextSubheadline.SemiBold,
            color: theme.Colors.Text.Error,
        },
        sectionWrapper: {
            borderWidth: 1,
            borderColor: theme.Colors.Border.Neutral300,
            overflow: 'hidden',
            borderRadius: theme.BorderRadius.md,
            backgroundColor: theme.Colors.Background.White,
            marginTop: theme.Size.Vertical.Medium,
            // marginHorizontal: theme.Size.Horizontal.Medium
        },
    };
});

export default DOPConfirmScreen;
