import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { HVICDetails, HVNFCDetails, HVPassportDetails, HVQRDetails, HVSelfieDetails } from '@src/domain/entities/hyperV/ekyc';
import { fetchBiometricInfo } from '../thunk';
import { BiometricInfoDataRes } from '@src/domain/entities/card_dop/biometricInfo';
import { CardDOPBaseResponse } from '@src/domain/entities/common/cardDOPBaseApi';
interface EKYCState {
    ICData: HVICDetails | null;
    isLoading: boolean;
    error: string | undefined;
    selfieData: HVSelfieDetails | null;
    HVNFCData: HVNFCDetails | null;
    HVQRData: HVQRDetails | null;
    countryId: string;
    HVPassportData: HVPassportDetails | null;
    biometricInfo: CardDOPBaseResponse<BiometricInfoDataRes>;
}

const initialState: EKYCState = {
    ICData: {
        additionalInfo: '',
        address: 'Ấp Ninh Thạnh 2 Ninh Hòa, Hồng Dân, Bạc Liêu',
        backImage: '/data/user/0/com.hdbank.dihdbank/files/hv/1742400658162.jpg',
        backRequestId: '1742400673856-f2fa0668-5748-43bf-bc8c-ab2f75f3c187',
        dateOfBirth: '29-08-2000',
        dateOfExpiry: '29-08-2025',
        dateOfIssue: '04-02-2022',
        district: 'HUYỆN HỒNG DÂN',
        frontImage: '/data/user/0/com.hdbank.dihdbank/files/hv/1742400649024.jpg',
        frontRequestId: '1742400654997-7001ef29-d614-485f-94fb-549b863f5c9c',
        gender: 'M',
        homeTown: 'Ninh Hòa, Hồng Dân, Bạc Liêu',
        houseNumber: '',
        idBackMrzDOB: '29-08-2000',
        idBackMrzDOE: '29-08-2025',
        idBackMrzFullName: 'PHAM VAN PHA',
        idBackMrzGender: 'M',
        idBackMrzIdNumber: '095200004966',
        idBackMrzNationality: 'VNM',
        idBackMrzValue: 'IDVNM2000049665095200004966<<70008291M2508290VNM<<<<<<<<<<<0PHAM<<VAN<PHA<<<<<<<<<<<<<<<<<',
        idNumber: '095200004966',
        idType: 'cccd_chip_front',
        name: 'PHẠM VĂN PHA',
        nationality: 'Việt Nam',
        placeOfIssue: 'CỤC TRƯỞNG CỤC CẢNH SÁT QUẢN LÝ HÀNH CHÍNH VỀ TRẬT TỰ XÃ HỘI',
        province: 'TỈNH BẠC LIÊU',
        street: '',
        yearOfBirth: '2000',
        zipCode: '',
        phoneNumber: '0989686869',
    },
    isLoading: false,
    error: undefined,
    selfieData: null,
    HVNFCData: null,
    HVQRData: null,
    countryId: 'vnm',
    HVPassportData: null,
    biometricInfo: {} as CardDOPBaseResponse<BiometricInfoDataRes>,
};

const OCRSlice = createSlice({
    name: 'OCRSlice',
    initialState,
    reducers: {
        updateSelectedCountry: (state, action: PayloadAction<{ countryId: string }>) => {
            state.countryId = action.payload.countryId;
        },
        updateICData: (state, action: PayloadAction<HVICDetails>) => {
            state.ICData = action.payload;
        },
        updateSelfieData: (state, action: PayloadAction<HVSelfieDetails>) => {
            state.selfieData = action.payload;
        },
        updateNFCData: (state, action: PayloadAction<HVNFCDetails>) => {
            state.HVNFCData = action.payload;
        },
        updateQRScanData: (state, action: PayloadAction<HVQRDetails>) => {
            state.HVQRData = action.payload;
        },
        updatePassportScanData: (state, action: PayloadAction<HVPassportDetails>) => {
            state.HVPassportData = action.payload;
        },
        setLoading: (state, action: PayloadAction<boolean>) => {
            state.isLoading = action.payload;
        },
        setError: (state, action: PayloadAction<string | undefined>) => {
            state.error = action.payload;
        },
        resetEKYC: (state) => {
            state.ICData = null;
            state.selfieData = null;
            state.HVNFCData = null;
            state.HVQRData = null;
            state.HVPassportData = null;
            state.error = undefined;
        },
    },
    extraReducers: (builder) => {
        builder
            .addCase(fetchBiometricInfo.pending, (state) => {
                state.isLoading = true;
                state.error = '';
            })
            .addCase(fetchBiometricInfo.rejected, (state, action) => {
                state.isLoading = false;
                state.error = action.error.message ?? 'Failed to register loan demand';
            })
            .addCase(fetchBiometricInfo.fulfilled, (state, action) => {
                state.isLoading = false;
                console.log('\x1b[36m', 'fetchBiometricInfo => fulfilled', action.payload);
                // console.log('\x1b[36m', 'confirmLoanRegister => fulfilled', action.payload);
                if (action.payload.resultCode === '00') {
                    state.biometricInfo = action.payload;
                } else {
                    state.error = 'Failed to register loan demand';
                }
            });
    },
});

export const {
    updateICData,
    setLoading,
    setError,
    updateSelfieData,
    updateNFCData,
    updateQRScanData,
    updateSelectedCountry,
    updatePassportScanData,
    resetEKYC,
} = OCRSlice.actions;
export default OCRSlice;
