import { injectable } from 'inversify';
import { Query } from '@src/domain/models/query';
import { HttpService } from '@core/service';
import { BASE_URL_CARD_DOP_API } from '@src/config';
import { CardDOPBaseResponse } from '@src/domain/entities/common/cardDOPBaseApi';
import { commonService } from '@src/infrastructure/network/networkService';
import { IAddCardInfoRepository } from '@src/domain/interfaces/card_dop/addCardInfo';
import { AddCardInfoDataReq, AddCardInfoDataRes } from '@src/domain/entities/card_dop/addCardInfo';

@injectable()
export class AddCardInfoRepository
    extends HttpService
    implements IAddCardInfoRepository {
    constructor() {
        super({ baseURL: BASE_URL_CARD_DOP_API });
    }

    async addCardInfo<TParameter>(query: Query<TParameter>): Promise<CardDOPBaseResponse<AddCardInfoDataRes>> {
        const request = query.query as unknown as AddCardInfoDataReq;
        const url = '/dop-add-card-info';
        const response = await this.post(url, request, {
            headers: commonService.getHeader({ 'X-CHANNEL': 'mfe-dop-mobile' }),
        })                
        console.log('\x1b[31m thieuvq3 response customer: ', response);
        return response.data as CardDOPBaseResponse<AddCardInfoDataRes>;
    }
}
