import React, { useState } from 'react';
import { TouchableOpacity, Text, Switch } from 'react-native';
import { useTranslation } from '@core/service';
import { useTheme } from '@core/ui';
import { createStyles } from '@core/ui';

interface BiometricButtonProps {
    icon: JSX.Element;
    toggleText: string;
    isEnabled: boolean;
    setIsEnabled: (v: boolean) => void;
}

const BiometricButton: React.FC<BiometricButtonProps> = ({ icon, toggleText, isEnabled, setIsEnabled }) => {
    const { t } = useTranslation(['module_dop']);
    const { theme } = useTheme();
    const styles = useStyles();

    const toggleSwitch = () => setIsEnabled(!isEnabled);

    return (
        <TouchableOpacity style={styles.faceIdButtonContainer}>
            {icon}
            <Text style={styles.faceIdButtonText}>{t(toggleText)}</Text>
            <Switch
                trackColor={{
                    false: theme.Colors.Border.Neutral400,
                    true: theme.Colors.Background.Success,
                }}
                thumbColor={isEnabled ? theme.Colors.Background.White : theme.Colors.Background.Neutral200}
                ios_backgroundColor={theme.Colors.Border.Neutral300}
                onValueChange={toggleSwitch}
                value={isEnabled}
            />
        </TouchableOpacity>
    );
};

const useStyles = createStyles((theme) => ({
    faceIdButtonContainer: {
        backgroundColor: theme.Colors.Background.White,
        borderWidth: 1,
        borderColor: theme.Colors.Border.Neutral400,
        borderRadius: theme.BorderRadius.md,
        padding: theme.Size.ModerateHorizontal.Medium,
        justifyContent: 'space-between',
        flexDirection: 'row',
        alignItems: 'center',
        marginTop: theme.Size.ModerateVertical.xLarge,
        width: '90%',
        alignSelf: 'center',
    },
    faceIdButtonText: {
        marginLeft: theme.Size.ModerateHorizontal.Small,
        marginRight: theme.Size.ModerateHorizontal.Small,
        color: theme.Colors.Text.Black,
    },
}));

export default BiometricButton;
