import {inject} from 'inversify';
import {TYPES} from '@src/di/types/types';
import {Query} from '@src/domain/models/query';
import { CardDOPBaseRequest } from '@src/domain/entities/common/cardDOPBaseApi';
import type { IConfirmCardInfoRepository } from '@src/domain/interfaces/card_dop/confirmCardInfo';
import { ConfirmCardInfoDataReq } from '@src/domain/entities/card_dop/confirmCardInfo';

export class ConfirmCardInfoHandler {
    private readonly _repository: IConfirmCardInfoRepository;

    constructor(
        @inject(TYPES.IConfirmCardInfoRepository)
        confirmCardInfoRepository: IConfirmCardInfoRepository
    ) {
        this._repository = confirmCardInfoRepository;
    }

    handle(query: Query<CardDOPBaseRequest<ConfirmCardInfoDataReq>>) {
        return this._repository.confirmCardInfo(query);
    }
}
